from __future__ import annotations

import csv
import io
import json
import os
import re
import tempfile
import uuid
from typing import Any, Dict, List, Optional

import requests

from langflow.custom.custom_component.component import Component
from langflow.io import (
    BoolInput,
    DropdownInput,
    HandleInput,
    IntInput,
    MessageTextInput,
